//! Fixture A (`fixtures/tiny`, generated by `tools/gen_tiny.py`): admission,
//! native execution and bit-exact parity with ONNX Runtime, plus one test per
//! negative variant. ORT outputs are read from `fixtures/tiny/ort.json`; the
//! native path never calls Tract or ORT.

use ndarray::Array2;
use serde_json::Value;
use tract_harvest_probe::admit::{self, Numeric, Refusal};
use tract_harvest_probe::provenance;
use tract_harvest_probe::source::SourceInventory;
use tract_onnx::prelude::*;

const DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/tiny");

fn bytes(v: &str) -> Vec<u8> {
    std::fs::read(format!("{DIR}/{v}.onnx")).unwrap()
}

fn ort() -> Value {
    serde_json::from_str(&std::fs::read_to_string(format!("{DIR}/ort.json")).unwrap()).unwrap()
}

fn inputs() -> (Vec<i32>, Array2<f32>) {
    let o = ort();
    let x = o["inputs"]["X"]["bits"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_i64().unwrap() as i32)
        .collect();
    let f: Vec<f32> = o["inputs"]["F"]["bits"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| f32::from_bits(v.as_u64().unwrap() as u32))
        .collect();
    (x, Array2::from_shape_vec((2, 3), f).unwrap())
}

fn ort_out(v: &str) -> (i32, Vec<u32>) {
    let o = ort();
    let e = &o["variants"][v]["ort"];
    (
        e["S"]["bits"][0].as_i64().unwrap() as i32,
        e["Q"]["bits"]
            .as_array()
            .unwrap()
            .iter()
            .map(|b| b.as_u64().unwrap() as u32)
            .collect(),
    )
}

fn admit_variant(v: &str) -> Result<admit::TinyRecipe, Refusal> {
    let b = bytes(v);
    let src = SourceInventory::from_bytes(&b).unwrap();
    let typed = admit::typed(&b)?;
    admit::admit_tiny(&src, &typed)
}

fn run(r: &admit::TinyRecipe) -> (i32, Vec<u32>) {
    let (x, f) = inputs();
    let mut scratch = vec![0u64; lance_graph_onnx::mask_words(x.len())];
    let (s, q) = r.run(&x, &f, &mut scratch).unwrap();
    assert!(!s.keepdims);
    (s.value, q.iter().map(|v| v.to_bits()).collect())
}

/// The recipe ran without Tract and agrees with ORT bit for bit.
#[test]
fn base_is_bit_exact_against_ort() {
    let r = admit_variant("base").unwrap();
    assert_eq!(r.receipt.numeric, Numeric::Exact);
    assert_eq!(r.receipt.opset, 18);
    assert_eq!(
        r.receipt.source_nodes,
        [
            "n_greater",
            "n_where",
            "n_reducesum",
            "n_add",
            "n_mul",
            "n_abs",
            "n_sqrt",
            "n_div"
        ]
    );
    // Z is in the receipt although Tract merged it into T (see below).
    let inits: Vec<&str> = r
        .receipt
        .initializers
        .iter()
        .map(|(n, _)| n.as_str())
        .collect();
    assert_eq!(inits, ["T", "Z", "axes", "B"]);
    assert_eq!(run(&r), ort_out("base"));
}

/// `div3` has a divisor (3) whose reciprocal is inexact. Over 256 seeded
/// inputs the native recipe (which keeps `Div`) and Tract's typed graph both
/// agree with ORT bit for bit; Tract's decluttered graph, which rewrites
/// `Div(Y, B)` into `Mul(Y, 1/B)`, does not. Only the column divided by 3 can
/// differ: the other divisors are powers of two, where the rewrite is exact.
#[test]
fn declutter_div_to_reciprocal_is_not_exact() {
    let r = admit_variant("div3").unwrap();
    let o = ort();
    let sweep = &o["div3_sweep"];
    let to_f = |v: &Value| -> Vec<f32> {
        v.as_array()
            .unwrap()
            .iter()
            .map(|b| f32::from_bits(b.as_u64().unwrap() as u32))
            .collect()
    };
    let to_u = |v: &Value| -> Vec<u32> {
        v.as_array()
            .unwrap()
            .iter()
            .map(|b| b.as_u64().unwrap() as u32)
            .collect()
    };
    let (x, _) = inputs();

    let typed = admit::typed(&bytes("div3")).unwrap();
    let decl = typed.clone().into_decluttered().unwrap();
    assert!(
        decl.nodes()
            .iter()
            .any(|n| n.name == "n_div-recip" && n.op.name() == "Const"),
        "the rewrite happened"
    );
    let typed = typed.into_runnable().unwrap();
    let decl = decl.into_runnable().unwrap();
    let tq = |m: &std::sync::Arc<TypedRunnableModel>, f: &Array2<f32>| -> Vec<u32> {
        let xi = tract_ndarray::Array1::from(x.clone())
            .into_dyn()
            .into_tensor();
        let out = m
            .run(tvec![xi.into(), f.clone().into_dyn().into_tensor().into()])
            .unwrap();
        out[1]
            .to_plain_array_view::<f32>()
            .unwrap()
            .iter()
            .map(|v| v.to_bits())
            .collect()
    };

    let mut scratch = vec![0u64; lance_graph_onnx::mask_words(x.len())];
    let (mut decl_diff, mut diff_cols) = (0usize, std::collections::BTreeSet::new());
    let n = sweep["F_bits"].as_array().unwrap().len();
    assert_eq!(n, 256);
    for (fb, qb) in sweep["F_bits"]
        .as_array()
        .unwrap()
        .iter()
        .zip(sweep["Q_bits"].as_array().unwrap())
    {
        let f = Array2::from_shape_vec((2, 3), to_f(fb)).unwrap();
        let want = to_u(qb);
        let native: Vec<u32> = r
            .run(&x, &f, &mut scratch)
            .unwrap()
            .1
            .iter()
            .map(|v| v.to_bits())
            .collect();
        assert_eq!(native, want, "native vs ORT");
        assert_eq!(tq(&typed, &f), want, "tract typed vs ORT");
        let d = tq(&decl, &f);
        for (i, (a, b)) in d.iter().zip(&want).enumerate() {
            if a != b {
                decl_diff += 1;
                diff_cols.insert(i % 3);
            }
        }
    }
    eprintln!(
        "decluttered Div->Mul(recip): {decl_diff} of {} elements differ from ORT",
        n * 6
    );
    assert!(decl_diff > 0, "the rewrite must be observable on 1/3");
    assert_eq!(
        diff_cols.into_iter().collect::<Vec<_>>(),
        [2],
        "only the divide-by-3 column"
    );
}

/// A recipe prepared from `base` refuses the `gen2` model (same shapes, new B
/// bytes); `gen2` admitted on its own matches its ORT output.
#[test]
fn stale_weight_generation_is_refused() {
    let base = admit_variant("base").unwrap();
    let gen2 = SourceInventory::from_bytes(&bytes("gen2")).unwrap();
    match base.receipt.check_generation(&gen2) {
        Err(Refusal::StaleGeneration { initializer, .. }) => assert_eq!(initializer, "B"),
        other => panic!("{other:?}"),
    }
    base.receipt
        .check_generation(&SourceInventory::from_bytes(&bytes("base")).unwrap())
        .unwrap();
    let r2 = admit_variant("gen2").unwrap();
    assert_eq!(run(&r2), ort_out("gen2"));
    assert_ne!(
        ort_out("gen2"),
        ort_out("base"),
        "the generations differ in output"
    );
}

/// `B` of shape `[4]` against `F` `[2,3]`. ORT refuses at load. Tract types
/// it, recording the impossible broadcast symbolically (`broadcast((3), (4))`),
/// and only fails when the plan runs. So a typed Tract model can carry an
/// unsatisfiable shape constraint, and admission must decide it: the native
/// broadcast check refuses before anything runs.
#[test]
fn incompatible_shape_is_refused() {
    assert!(ort()["variants"]["neg_shape"]["ort_error"]
        .as_str()
        .unwrap()
        .contains("Incompatible"));
    let typed = admit::typed(&bytes("neg_shape")).expect("Tract types the impossible broadcast");
    let add = typed.nodes().iter().find(|n| n.name == "n_add").unwrap();
    assert!(
        format!("{:?}", add.outputs[0].fact).contains("broadcast((3), (4))"),
        "{:?}",
        add.outputs[0].fact
    );
    match admit_variant("neg_shape") {
        Err(Refusal::Native(lance_graph_onnx::Refusal::Broadcast { lhs, rhs })) => {
            assert_eq!((lhs, rhs), (vec![2, 3], vec![4]))
        }
        other => panic!("{other:?}"),
    }
}

/// `Where(c, X, 1)`: the masked-sum rewrite does not hold, and ORT shows it
/// (17, not the masked sum 14). Admission refuses the rewrite.
#[test]
fn invalid_rewrite_assumption_is_refused() {
    assert_eq!(ort_out("neg_where_nonzero").0, 17);
    assert_eq!(ort_out("base").0, 14);
    match admit_variant("neg_where_nonzero") {
        Err(Refusal::RewriteAssumption { node, .. }) => assert_eq!(node, "n_where"),
        other => panic!("{other:?}"),
    }
}

/// `Erf` in place of `Abs`: Tract imports it, ORT runs it, the method has no
/// native counterpart, so admission refuses by name.
#[test]
fn unsupported_operator_is_refused() {
    assert!(
        admit::typed(&bytes("neg_unsupported")).is_ok(),
        "Tract imports Erf"
    );
    match admit_variant("neg_unsupported") {
        Err(Refusal::UnsupportedOp { node, op_type }) => {
            assert_eq!((node.as_str(), op_type.as_str()), ("n_abs", "Erf"))
        }
        other => panic!("{other:?}"),
    }
}

/// `com.example:Abs`: ORT refuses it, Tract imports it as the default-domain
/// `Abs` (its op registry is keyed by `op_type` only). The domain survives only
/// in the source inventory, and admission refuses from there.
#[test]
fn foreign_domain_is_refused_although_tract_accepts_it() {
    assert!(ort()["variants"]["neg_domain"]["ort_error"]
        .as_str()
        .unwrap()
        .contains("com.example:Abs"));
    let typed = admit::typed(&bytes("neg_domain")).expect("Tract ignores the domain");
    assert!(typed
        .nodes()
        .iter()
        .any(|n| n.name == "n_abs" && n.op.name() == "Abs"));
    match admit_variant("neg_domain") {
        Err(Refusal::ForeignDomain { node, domain }) => {
            assert_eq!((node.as_str(), domain.as_str()), ("n_abs", "com.example"))
        }
        other => panic!("{other:?}"),
    }
}

/// A runtime fact the graph cannot show: a sum past int32 is refused, not wrapped.
#[test]
fn int32_overflow_is_refused_at_run_time() {
    let r = admit_variant("base").unwrap();
    let x = vec![i32::MAX, 1, 1];
    let mut scratch = vec![0u64; 1];
    let f = Array2::<f32>::zeros((2, 3));
    match r.run(&x, &f, &mut scratch) {
        Err(Refusal::Native(lance_graph_onnx::Refusal::OutOfDtypeRange(v))) => {
            assert_eq!(v, i32::MAX as i64 + 2)
        }
        other => panic!("{other:?}"),
    }
}

/// Tract's `InferenceModel::add_const` returns an existing constant of equal
/// value, so the two source initializers `T = 0` and `Z = 0` become one node
/// named `T`. With `Z = 1` both survive. This is why initializer identity is
/// read from the source inventory, never from Tract's graph.
#[test]
fn tract_merges_equal_constants() {
    let names = |v: &str| -> Vec<String> {
        let onnx = tract_onnx::onnx();
        let p = onnx.proto_model_for_read(&mut &*bytes(v)).unwrap();
        onnx.model_for_proto_model(&p)
            .unwrap()
            .nodes()
            .iter()
            .map(|n| n.name.clone())
            .collect()
    };
    let base = names("base");
    assert!(
        base.contains(&"T".into()) && !base.contains(&"Z".into()),
        "{base:?}"
    );
    let nz = names("neg_where_nonzero");
    assert!(nz.contains(&"T".into()) && nz.contains(&"Z".into()));
}

/// Per-stage provenance on `base`, counted against the raw protobuf.
#[test]
fn provenance_per_stage() {
    let b = bytes("base");
    let src = SourceInventory::from_bytes(&b).unwrap();
    let onnx = tract_onnx::onnx();
    let inf = onnx
        .model_for_proto_model(&onnx.proto_model_for_read(&mut &*b).unwrap())
        .unwrap();
    let typed = inf.clone().into_typed().unwrap();
    let decl = typed.clone().into_decluttered().unwrap();
    let p_inf = provenance::of_graph("inference", &src, &inf);
    let p_typed = provenance::of_graph("typed", &src, &typed);
    let p_decl = provenance::of_graph("decluttered", &src, &decl);
    for p in [&p_inf, &p_typed] {
        assert_eq!(p.source_names_kept, 8, "{p:?}");
        assert!(p.source_names_lost.is_empty(), "{p:?}");
    }
    // Declutter keeps every node name here, but changes n_div's op (Div -> Mul).
    assert_eq!(p_decl.source_names_kept, 8, "{p_decl:?}");
    assert!(decl
        .nodes()
        .iter()
        .any(|n| n.name == "n_div" && n.op.name() == "Mul"));
    assert!(
        p_typed.synthesized_names > 0,
        "fix-rank / dispose-dims nodes: {p_typed:?}"
    );
}
